    x = np.asarray(xs, dtype=float)
    y = np.asarray(ys, dtype=float)
    usable = np.isfinite(x) & np.isfinite(y)
    if usable.sum() < 2:
        return
    slope, intercept = np.polyfit(x[usable], y[usable], 1)
